import requests, os

api_key = open(os.environ['GALAXY_API_KEY_FILE']).read().strip()
hist_id = 'bbd44e69cb8906b587ee340204072eed'

# Upload all gene lists to Galaxy
gene_lists = {}
for strain in ['97', '98', '99']:
    for direction in ['up', 'down']:
        fname = f'strain{strain}_{direction}.txt'
        fpath = f'/tmp/gene_lists/{fname}'

        with open(fpath, 'rb') as f:
            r = requests.post(
                f'https://usegalaxy.org/api/tools/upload',
                data={
                    'history_id': hist_id,
                },
                files={'files_0|file_data': (fname, f)},
                params={
                    'key': api_key
                }
            )
        if r.status_code == 200:
            result = r.json()
            if 'outputs' in result and len(result['outputs']) > 0:
                ds_id = result['outputs'][0]['id']
                gene_lists[f'{strain}_{direction}'] = ds_id
                print(f'Uploaded {fname}: {ds_id}')
            else:
                print(f'Upload {fname}: unexpected response: {r.text[:200]}')
        else:
            print(f'Upload {fname} failed: {r.status_code} {r.text[:200]}')

print('\nGene list dataset IDs:')
for k, v in gene_lists.items():
    print(f'  {k}: {v}')
